from __future__ import annotations

import json
import os
from dataclasses import dataclass


def _as_bool(value: str | None, default: bool = False) -> bool:
    if value is None:
        return default
    return value.lower() in {"1", "true", "yes", "on"}


@dataclass(frozen=True, slots=True)
class Settings:
    alpaca_key: str | None
    alpaca_secret: str | None
    state_backend: str
    competition_id: str
    aws_region: str
    dynamodb_table: str
    dynamodb_endpoint_url: str | None
    auto_reconcile: bool
    public_delay_seconds: int
    runtime_role: str = "local"
    worker_poll_seconds: int = 60
    cors_origins: tuple[str, ...] = ("http://localhost:3000", "http://127.0.0.1:3000")
    challenger_manifest_uri: str | None = None
    challenger_manifest_sha256: str | None = None
    paper_execution_enabled: bool = False

    def __post_init__(self) -> None:
        if self.state_backend not in {"memory", "dynamodb"}:
            raise ValueError("STATE_BACKEND must be memory or dynamodb")
        if self.public_delay_seconds < 0:
            raise ValueError("PUBLIC_DELAY_SECONDS must be nonnegative")
        if self.runtime_role not in {"local", "reporting", "worker"}:
            raise ValueError("RUNTIME_ROLE must be local, reporting, or worker")
        if self.worker_poll_seconds < 1:
            raise ValueError("WORKER_POLL_SECONDS must be positive")

    @classmethod
    def from_env(cls) -> Settings:
        alpaca_key = os.getenv("ALPACA_KEY")
        alpaca_secret = os.getenv("ALPACA_SECRET")
        packed_credentials = os.getenv("ALPACA_CREDENTIALS")
        if packed_credentials and (not alpaca_key or not alpaca_secret):
            credentials = json.loads(packed_credentials)
            if not isinstance(credentials, dict):
                raise ValueError("ALPACA_CREDENTIALS must be a JSON object")
            alpaca_key = alpaca_key or credentials.get("ALPACA_KEY")
            alpaca_secret = alpaca_secret or credentials.get("ALPACA_SECRET")
            if not isinstance(alpaca_key, str) or not isinstance(alpaca_secret, str):
                raise ValueError("ALPACA_CREDENTIALS must contain string key and secret values")
        return cls(
            alpaca_key=alpaca_key,
            alpaca_secret=alpaca_secret,
            state_backend=os.getenv("STATE_BACKEND", "memory"),
            competition_id=os.getenv("COMPETITION_ID", "local-development"),
            aws_region=os.getenv("AWS_REGION", "us-east-1"),
            dynamodb_table=os.getenv("DYNAMODB_TABLE", "catalyst-router-local"),
            dynamodb_endpoint_url=os.getenv("DYNAMODB_ENDPOINT_URL"),
            auto_reconcile=_as_bool(os.getenv("AUTO_RECONCILE")),
            public_delay_seconds=int(os.getenv("PUBLIC_DELAY_SECONDS", "900")),
            runtime_role=os.getenv("RUNTIME_ROLE", "local"),
            worker_poll_seconds=int(os.getenv("WORKER_POLL_SECONDS", "60")),
            cors_origins=tuple(
                origin.strip()
                for origin in os.getenv(
                    "CORS_ORIGINS", "http://localhost:3000,http://127.0.0.1:3000"
                ).split(",")
                if origin.strip()
            ),
            challenger_manifest_uri=os.getenv("CHALLENGER_MANIFEST_URI"),
            challenger_manifest_sha256=os.getenv("CHALLENGER_MANIFEST_SHA256"),
            paper_execution_enabled=_as_bool(os.getenv("PAPER_EXECUTION_ENABLED")),
        )

    def require_alpaca(self) -> tuple[str, str]:
        if not self.alpaca_key or not self.alpaca_secret:
            raise RuntimeError("ALPACA_KEY and ALPACA_SECRET are required")
        return self.alpaca_key, self.alpaca_secret

from __future__ import annotations

import hashlib
import json
from datetime import UTC, datetime, timedelta
from decimal import ROUND_CEILING, ROUND_FLOOR, Decimal
from typing import Protocol
from uuid import NAMESPACE_URL, uuid5

from catalyst_router.domain import (
    AgentMode,
    BrokerOrderSnapshot,
    DecisionRecord,
    InstrumentType,
    OrderExecution,
    OrderExecutionStatus,
    OrderPlan,
    PortfolioRiskState,
    QuoteSnapshot,
    ReconciliationSnapshot,
    RiskDecision,
    RiskDecisionStatus,
    Route,
    Side,
    TradeIntent,
)
from catalyst_router.ports import OperationalStore, PaperBroker
from catalyst_router.risk import RiskGovernor
from catalyst_router.training import FEATURE_SCHEMA, FeatureVector

_CENT = Decimal("0.01")


class IncumbentStrategy:
    """Conservative deterministic policy authorized for the first paper execution slice."""

    MAX_QUOTE_AGE = timedelta(seconds=5)
    MAX_FEATURE_AGE = timedelta(minutes=20)
    MAX_SPREAD_BPS = Decimal("15")

    def create_intent(
        self,
        vector: FeatureVector,
        quote: QuoteSnapshot,
        *,
        now: datetime | None = None,
    ) -> TradeIntent | None:
        observed_now = now or datetime.now(UTC)
        if vector.schema != FEATURE_SCHEMA or quote.symbol != vector.symbol:
            return None
        feature_age = observed_now - vector.observed_at
        quote_age = observed_now - quote.timestamp
        if not timedelta(0) <= feature_age <= self.MAX_FEATURE_AGE:
            return None
        if not timedelta(0) <= quote_age <= self.MAX_QUOTE_AGE:
            return None
        if quote.spread_bps > self.MAX_SPREAD_BPS:
            return None

        route = self.route(vector)
        if route is None:
            return None

        confidence = Decimal("0.85") if route is Route.REGIME_TREND else Decimal("0.80")
        entry_price = quote.ask_price.quantize(_CENT, rounding=ROUND_CEILING)
        stop_price = (entry_price * Decimal("0.98")).quantize(_CENT, rounding=ROUND_FLOOR)
        intent_id = str(
            uuid5(
                NAMESPACE_URL,
                f"incumbent-v1:{route}:{vector.symbol}:{vector.observed_at.isoformat()}",
            )
        )
        return TradeIntent(
            intent_id=intent_id,
            route=route,
            symbol=vector.symbol,
            instrument_type=InstrumentType.EQUITY,
            side=Side.BUY,
            confidence=confidence,
            entry_price=entry_price,
            stop_price=stop_price,
            expected_horizon_minutes=60 if route is Route.LIQUIDITY_REVERSION else 240,
            exposure_group="us-equity:long",
            quote_age_seconds=Decimal(str(quote_age.total_seconds())),
            data_quality_passed=True,
        )

    @staticmethod
    def route(vector: FeatureVector) -> Route | None:
        if vector.schema != FEATURE_SCHEMA:
            return None
        features = dict(zip(vector.names, vector.values, strict=True))
        if vector.symbol in {"SPY", "QQQ"} and (
            features["return_1"] > 0
            and features["return_4"] >= 0.002
            and features["return_12"] >= 0.005
            and features["close_location_20"] >= 0.2
        ):
            return Route.REGIME_TREND
        elif vector.symbol not in {"SPY", "QQQ"} and (
            features["return_1"] >= 0.0005
            and features["relative_return_4"] <= -0.005
            and features["vwap_distance"] >= 0
            and features["close_location_20"] <= -0.3
            and features["cross_sectional_return_rank_4"] <= -0.35
        ):
            return Route.LIQUIDITY_REVERSION
        return None


class QuoteSource(Protocol):
    def latest_quote(self, symbol: str) -> QuoteSnapshot: ...


class LiveTradingCycle:
    """Evaluates the incumbent and submits at most one protected equity entry."""

    MAX_ENTRY_NOTIONAL_RATE = Decimal("0.10")

    def __init__(
        self,
        *,
        store: OperationalStore,
        broker: PaperBroker,
        quotes: QuoteSource,
        strategy: IncumbentStrategy | None = None,
        risk_governor: RiskGovernor | None = None,
    ) -> None:
        self._store = store
        self._broker = broker
        self._quotes = quotes
        self._strategy = strategy or IncumbentStrategy()
        self._risk = risk_governor or RiskGovernor()
        self._gateway = ExecutionGateway(store=store, broker=broker)

    def run(
        self, vectors: tuple[FeatureVector, ...], *, expected_epoch: str
    ) -> tuple[DecisionRecord, ...]:
        agent = self._store.get_agent_state()
        if agent.mode is not AgentMode.RUNNING:
            return ()
        if agent.execution_epoch != expected_epoch or not agent.is_reconciled:
            raise RuntimeError("worker lost execution epoch ownership")

        snapshot = self._broker.reconciliation_snapshot()
        agent = self._store.update_equity_peak(snapshot.account.equity)
        active_execution = (
            self._store.get_order(agent.active_order_id)
            if agent.active_order_id is not None
            else None
        )
        until_close = snapshot.clock.next_close - snapshot.clock.timestamp
        if active_execution is not None:
            self._release_terminal_order(
                agent.active_order_id or active_execution.plan.client_order_id,
                snapshot,
                active_execution,
            )
            agent = self._store.get_agent_state()
            active_execution = (
                self._store.get_order(agent.active_order_id)
                if agent.active_order_id is not None
                else None
            )
        horizon_expired = (
            active_execution is not None
            and snapshot.clock.timestamp >= active_execution.plan.expires_at
        )
        close_flatten_due = bool(
            snapshot.positions or snapshot.open_orders
        ) and until_close <= timedelta(minutes=10)
        if horizon_expired or close_flatten_due:
            self._broker.flatten()
            return ()
        last_equity = snapshot.account.last_equity or snapshot.account.equity
        equity_peak = agent.equity_peak or max(last_equity, snapshot.account.equity)
        portfolio = PortfolioRiskState(
            equity=snapshot.account.equity,
            buying_power=min(
                snapshot.account.buying_power,
                snapshot.account.equity * self.MAX_ENTRY_NOTIONAL_RATE,
            ),
            position_count=0,
            total_open_risk=Decimal("0"),
            overnight_open_risk=Decimal("0"),
            group_open_risk={},
            daily_pnl=snapshot.account.equity - last_equity,
            competition_drawdown=max(
                Decimal("0"),
                (equity_peak - snapshot.account.equity) / equity_peak,
            ),
        )
        daily_loss = max(Decimal("0"), -portfolio.daily_pnl)
        if portfolio.competition_drawdown >= RiskGovernor.MAX_COMPETITION_DRAWDOWN_RATE:
            self._halt_and_flatten(AgentMode.KILLED, "competition drawdown kill threshold reached")
            return ()
        if daily_loss >= portfolio.equity * RiskGovernor.MAX_DAILY_LOSS_RATE:
            self._halt_and_flatten(AgentMode.RISK_HALTED, "daily loss circuit breaker reached")
            return ()
        if snapshot.positions and len(snapshot.open_orders) < 2:
            self._halt_and_flatten(
                AgentMode.RISK_HALTED,
                "broker position is missing protective bracket exits",
            )
            return ()
        if (
            agent.active_order_id is not None
            or not snapshot.clock.is_open
            or snapshot.account.trading_blocked
            or snapshot.positions
            or snapshot.open_orders
            or until_close <= timedelta(minutes=15)
        ):
            return ()
        for vector in sorted(vectors, key=lambda item: item.symbol):
            if self._strategy.route(vector) is None:
                continue
            quote = self._quotes.latest_quote(vector.symbol)
            intent = self._strategy.create_intent(vector, quote)
            if intent is None:
                continue
            risk = self._risk.evaluate(
                intent,
                agent,
                portfolio,
                market_is_open=snapshot.clock.is_open,
                trading_blocked=snapshot.account.trading_blocked,
            )
            if risk.status is RiskDecisionStatus.VETOED:
                return self._persist_risk_veto(intent, risk, expected_epoch)
            approvals = self._persist_risk_approval(intent, risk, portfolio, expected_epoch)
            execution = self._gateway.execute(intent, risk, expected_epoch=expected_epoch)
            return approvals + self._persist_execution(intent, risk, execution, expected_epoch)
        return ()

    def _release_terminal_order(
        self,
        client_order_id: str,
        snapshot: ReconciliationSnapshot,
        execution: OrderExecution,
    ) -> None:
        broker_order = self._broker.get_order_by_client_id(client_order_id)
        status = (
            broker_order.status.rsplit(".", 1)[-1].lower()
            if broker_order is not None
            else "missing"
        )
        terminal = status in {"canceled", "expired", "filled", "rejected", "replaced"}
        expired_and_missing = (
            status == "missing" and snapshot.clock.timestamp >= execution.plan.expires_at
        )
        if (
            (terminal or expired_and_missing)
            and not snapshot.positions
            and not snapshot.open_orders
        ):
            self._store.clear_active_order(client_order_id)

    def _halt_and_flatten(self, mode: AgentMode, reason: str) -> None:
        self._store.transition_agent_mode(
            mode,
            reason=reason,
            record=DecisionRecord.create(
                decision_type="CIRCUIT_BREAKER",
                summary=reason,
                payload={"mode": mode, "reason": reason},
            ),
        )
        self._broker.flatten()

    def _persist_risk_veto(
        self, intent: TradeIntent, risk: RiskDecision, expected_epoch: str
    ) -> tuple[DecisionRecord, ...]:
        record = DecisionRecord.create(
            decision_id=str(uuid5(NAMESPACE_URL, f"risk-veto:{intent.intent_id}")),
            decision_type="RISK_VETO",
            route=intent.route,
            symbol=intent.symbol,
            summary="; ".join(risk.checks),
            payload={"intent_id": intent.intent_id, "checks": risk.checks},
            public=True,
            public_summary=f"Risk governor vetoed {intent.symbol}",
        )
        return (
            (record,)
            if self._store.append_decision_once(record, expected_epoch=expected_epoch)
            else ()
        )

    def _persist_risk_approval(
        self,
        intent: TradeIntent,
        risk: RiskDecision,
        portfolio: PortfolioRiskState,
        expected_epoch: str,
    ) -> tuple[DecisionRecord, ...]:
        record = DecisionRecord.create(
            decision_id=str(uuid5(NAMESPACE_URL, f"risk-approval:{intent.intent_id}")),
            decision_type="RISK_APPROVAL",
            route=intent.route,
            symbol=intent.symbol,
            summary=f"approved {risk.quantity} shares with {risk.risk_amount} stop risk",
            payload={
                "intent_id": intent.intent_id,
                "status": risk.status,
                "quantity": risk.quantity,
                "risk_amount": str(risk.risk_amount),
                "checks": risk.checks,
                "account_snapshot": {
                    "equity": str(portfolio.equity),
                    "buying_power": str(portfolio.buying_power),
                    "position_count": portfolio.position_count,
                    "total_open_risk": str(portfolio.total_open_risk),
                    "daily_pnl": str(portfolio.daily_pnl),
                    "competition_drawdown": str(portfolio.competition_drawdown),
                },
            },
        )
        return (
            (record,)
            if self._store.append_decision_once(record, expected_epoch=expected_epoch)
            else ()
        )

    def _persist_execution(
        self,
        intent: TradeIntent,
        risk: RiskDecision,
        execution: OrderExecution,
        expected_epoch: str,
    ) -> tuple[DecisionRecord, ...]:
        record = DecisionRecord.create(
            decision_id=str(
                uuid5(NAMESPACE_URL, f"order-execution:{execution.plan.client_order_id}")
            ),
            decision_type="ORDER_EXECUTION",
            route=intent.route,
            symbol=intent.symbol,
            summary=(
                f"{execution.status} paper bracket {execution.plan.client_order_id} "
                f"for {execution.plan.quantity} {intent.symbol}"
            ),
            payload={
                "client_order_id": execution.plan.client_order_id,
                "status": execution.status,
                "quantity": execution.plan.quantity,
                "risk_amount": str(risk.risk_amount),
                "limit_price": str(execution.plan.limit_price),
                "stop_price": str(execution.plan.stop_price),
                "take_profit_price": str(execution.plan.take_profit_price),
            },
            public=True,
            public_summary=f"Paper bracket order {execution.status.lower()} for {intent.symbol}",
        )
        return (
            (record,)
            if self._store.append_decision_once(record, expected_epoch=expected_epoch)
            else ()
        )


class ExecutionGateway:
    def __init__(self, *, store: OperationalStore, broker: PaperBroker) -> None:
        self._store = store
        self._broker = broker

    def execute(
        self,
        intent: TradeIntent,
        risk: RiskDecision,
        *,
        expected_epoch: str,
    ) -> OrderExecution:
        if risk.intent_id != intent.intent_id or risk.status is RiskDecisionStatus.VETOED:
            raise ValueError("an approved risk decision matching the intent is required")
        plan = self._plan(intent, risk)
        prepared = OrderExecution(plan=plan, request_hash=self._request_hash(plan))
        claimed = self._store.claim_order(prepared, expected_epoch=expected_epoch)
        execution = prepared if claimed else self._store.get_order(plan.client_order_id)
        if execution is None:
            raise RuntimeError("claimed order execution could not be loaded")
        if execution.request_hash != prepared.request_hash:
            raise RuntimeError("client order id was reused with a different request")
        if execution.status in {
            OrderExecutionStatus.ACKNOWLEDGED,
            OrderExecutionStatus.REJECTED,
        }:
            return execution

        broker_order = self._broker.get_order_by_client_id(plan.client_order_id)
        if broker_order is not None:
            return self._acknowledge(execution, broker_order)
        try:
            broker_order = self._broker.submit_order(plan)
        except Exception:
            broker_order = self._broker.get_order_by_client_id(plan.client_order_id)
            if broker_order is not None:
                return self._acknowledge(execution, broker_order)
            return self._transition(execution, OrderExecutionStatus.UNKNOWN)
        return self._acknowledge(execution, broker_order)

    @staticmethod
    def _plan(intent: TradeIntent, risk: RiskDecision) -> OrderPlan:
        client_order_id = "cr-" + uuid5(NAMESPACE_URL, f"paper-order-v1:{intent.intent_id}").hex
        take_profit = (intent.entry_price * Decimal("1.04")).quantize(_CENT, rounding=ROUND_CEILING)
        created_at = datetime.now(UTC)
        return OrderPlan(
            client_order_id=client_order_id,
            intent_id=intent.intent_id,
            symbol=intent.symbol,
            side=intent.side,
            quantity=risk.quantity,
            limit_price=intent.entry_price,
            stop_price=intent.stop_price,
            take_profit_price=take_profit,
            risk_amount=risk.risk_amount,
            exposure_group=intent.exposure_group,
            created_at=created_at,
            expires_at=created_at + timedelta(minutes=intent.expected_horizon_minutes),
        )

    @staticmethod
    def _request_hash(plan: OrderPlan) -> str:
        request = {
            "client_order_id": plan.client_order_id,
            "limit_price": str(plan.limit_price),
            "quantity": plan.quantity,
            "side": plan.side,
            "stop_price": str(plan.stop_price),
            "symbol": plan.symbol,
            "take_profit_price": str(plan.take_profit_price),
            "time_in_force": "day",
            "type": "limit",
        }
        encoded = json.dumps(request, sort_keys=True, separators=(",", ":")).encode()
        return hashlib.sha256(encoded).hexdigest()

    def _acknowledge(
        self, execution: OrderExecution, broker_order: BrokerOrderSnapshot
    ) -> OrderExecution:
        plan = execution.plan
        if (
            broker_order.client_order_id != plan.client_order_id
            or broker_order.symbol != plan.symbol
            or broker_order.side is not plan.side
            or broker_order.quantity != plan.quantity
        ):
            raise RuntimeError("Alpaca order does not match the durable order plan")
        status = broker_order.status.rsplit(".", 1)[-1].lower()
        target = (
            OrderExecutionStatus.REJECTED
            if status in {"canceled", "expired", "rejected", "replaced"}
            else OrderExecutionStatus.ACKNOWLEDGED
        )
        updated = self._transition(
            execution,
            target,
            alpaca_order_id=broker_order.order_id,
            broker_status=broker_order.status,
        )
        if target is OrderExecutionStatus.REJECTED:
            self._store.clear_active_order(plan.client_order_id)
        return updated

    def _transition(
        self,
        execution: OrderExecution,
        status: OrderExecutionStatus,
        *,
        alpaca_order_id: str | None = None,
        broker_status: str | None = None,
    ) -> OrderExecution:
        updated = execution.model_copy(
            update={
                "status": status,
                "version": execution.version + 1,
                "alpaca_order_id": alpaca_order_id or execution.alpaca_order_id,
                "broker_status": broker_status or execution.broker_status,
                "updated_at": datetime.now(UTC),
            }
        )
        return self._store.update_order(updated, expected_status=execution.status)

from decimal import ROUND_FLOOR, Decimal

from catalyst_router.domain import (
    AgentMode,
    AgentState,
    InstrumentType,
    PortfolioRiskState,
    RiskDecision,
    RiskDecisionStatus,
    Route,
    Side,
    TradeIntent,
)


class RiskGovernor:
    MAX_POSITIONS = 6
    MAX_TRADE_RISK_RATE = Decimal("0.01")
    REDUCED_TRADE_RISK_RATE = Decimal("0.005")
    MAX_TOTAL_RISK_RATE = Decimal("0.04")
    MAX_OVERNIGHT_RISK_RATE = Decimal("0.02")
    MAX_GROUP_RISK_RATE = Decimal("0.02")
    DE_RISK_DAILY_LOSS_RATE = Decimal("0.02")
    MAX_DAILY_LOSS_RATE = Decimal("0.04")
    MAX_COMPETITION_DRAWDOWN_RATE = Decimal("0.12")
    MAX_QUOTE_AGE_SECONDS = Decimal("5")

    def __init__(self, *, options_execution_enabled: bool = False) -> None:
        self._options_execution_enabled = options_execution_enabled

    def evaluate(
        self,
        intent: TradeIntent,
        agent: AgentState,
        portfolio: PortfolioRiskState,
        *,
        market_is_open: bool,
        overnight: bool = False,
        trading_blocked: bool = False,
    ) -> RiskDecision:
        vetoes: list[str] = []
        if intent.route is Route.NO_TRADE:
            vetoes.append("NO_TRADE cannot create exposure")
        if intent.instrument_type is InstrumentType.OPTION and intent.side is not Side.BUY:
            vetoes.append("short option legs are prohibited")
        if intent.instrument_type is InstrumentType.OPTION and not self._options_execution_enabled:
            vetoes.append("live option execution is not enabled")
        if intent.route is Route.LIQUIDITY_REVERSION and (
            intent.instrument_type is not InstrumentType.EQUITY
        ):
            vetoes.append("liquidity reversion must use equities")
        if intent.route is Route.REGIME_TREND and (
            intent.instrument_type is not InstrumentType.EQUITY
        ):
            vetoes.append("regime trend must use equities")
        if trading_blocked:
            vetoes.append("Alpaca account is blocked from trading")
        if agent.mode is not AgentMode.RUNNING:
            vetoes.append(f"agent mode is {agent.mode}")
        if not agent.is_reconciled:
            vetoes.append("startup reconciliation is incomplete")
        if not market_is_open:
            vetoes.append("market is closed")
        if not intent.data_quality_passed:
            vetoes.append("intent data failed quality gates")
        if intent.quote_age_seconds > self.MAX_QUOTE_AGE_SECONDS:
            vetoes.append("quote is stale")
        if intent.stop_distance <= 0:
            vetoes.append("stop distance must be positive")
        if intent.side is Side.BUY and intent.stop_price >= intent.entry_price:
            vetoes.append("buy stop must be below entry")
        if intent.side is Side.SELL and intent.stop_price <= intent.entry_price:
            vetoes.append("sell stop must be above entry")
        if portfolio.position_count >= self.MAX_POSITIONS:
            vetoes.append("maximum position count reached")

        daily_loss = max(Decimal("0"), -portfolio.daily_pnl)
        if daily_loss >= portfolio.equity * self.MAX_DAILY_LOSS_RATE:
            vetoes.append("daily loss circuit breaker reached")
        if portfolio.competition_drawdown >= self.MAX_COMPETITION_DRAWDOWN_RATE:
            vetoes.append("competition drawdown kill threshold reached")

        if vetoes:
            return self._veto(intent, vetoes)

        risk_rate = (
            self.REDUCED_TRADE_RISK_RATE
            if daily_loss >= portfolio.equity * self.DE_RISK_DAILY_LOSS_RATE
            else self.MAX_TRADE_RISK_RATE
        )
        allowed_risk = portfolio.equity * risk_rate
        total_capacity = portfolio.equity * self.MAX_TOTAL_RISK_RATE - portfolio.total_open_risk
        group_capacity = (
            portfolio.equity * self.MAX_GROUP_RISK_RATE
            - portfolio.group_open_risk.get(intent.exposure_group, Decimal("0"))
        )
        capacities = [allowed_risk, total_capacity, group_capacity]
        if overnight:
            capacities.append(
                portfolio.equity * self.MAX_OVERNIGHT_RISK_RATE - portfolio.overnight_open_risk
            )
        risk_amount = max(Decimal("0"), min(capacities))
        affordable = (portfolio.buying_power / intent.entry_cost_per_unit).to_integral_value(
            rounding=ROUND_FLOOR
        )
        by_stop = (risk_amount / intent.stop_risk_per_unit).to_integral_value(rounding=ROUND_FLOOR)
        quantity = int(min(affordable, by_stop))
        if quantity < 1:
            return self._veto(intent, ["risk or buying-power capacity is insufficient"])

        actual_risk = intent.stop_risk_per_unit * quantity
        status = (
            RiskDecisionStatus.REDUCED
            if risk_amount < allowed_risk or risk_rate < self.MAX_TRADE_RISK_RATE
            else RiskDecisionStatus.APPROVED
        )
        return RiskDecision(
            status=status,
            intent_id=intent.intent_id,
            quantity=quantity,
            risk_amount=actual_risk,
            checks=(
                "agent running and reconciled",
                "data and market gates passed",
                "trade, portfolio, group, and buying-power limits passed",
            ),
        )

    @staticmethod
    def _veto(intent: TradeIntent, vetoes: list[str]) -> RiskDecision:
        return RiskDecision(
            status=RiskDecisionStatus.VETOED,
            intent_id=intent.intent_id,
            quantity=0,
            risk_amount=Decimal("0"),
            checks=tuple(vetoes),
        )

from __future__ import annotations

import argparse
import json
import logging

import uvicorn
from dotenv import load_dotenv

from catalyst_router.adapters.alpaca import AlpacaPaperBroker
from catalyst_router.container import Container
from catalyst_router.domain import AgentMode, DecisionRecord
from catalyst_router.service import ReconciliationService
from catalyst_router.settings import Settings


def _check_alpaca(settings: Settings) -> int:
    key, secret = settings.require_alpaca()
    snapshot = AlpacaPaperBroker(key, secret).reconciliation_snapshot()
    print(
        json.dumps(
            {
                "paper": True,
                "market_is_open": snapshot.clock.is_open,
                "equity": str(snapshot.account.equity),
                "buying_power": str(snapshot.account.buying_power),
                "trading_blocked": snapshot.account.trading_blocked,
                "options_trading_level": snapshot.account.options_trading_level,
                "position_count": len(snapshot.positions),
                "open_order_count": len(snapshot.open_orders),
            },
            indent=2,
        )
    )
    return 0


def _reconcile(settings: Settings) -> int:
    container = Container.build(settings)
    snapshot = container.reconciliation_service().reconcile()
    state = container.store.get_agent_state()
    print(
        json.dumps(
            {
                "paper": True,
                "mode": state.mode,
                "reconciled": state.is_reconciled,
                "market_is_open": snapshot.clock.is_open,
                "position_count": len(snapshot.positions),
                "open_order_count": len(snapshot.open_orders),
            },
            indent=2,
        )
    )
    return 0


def _worker(settings: Settings) -> int:
    if settings.runtime_role != "worker":
        raise RuntimeError("worker command requires RUNTIME_ROLE=worker")
    container = Container.build(settings)
    container.trading_worker().run_forever(
        reconcile=container.reconciliation_service().reconcile,
        poll_seconds=settings.worker_poll_seconds,
    )
    return 0


def _set_mode(settings: Settings, mode: AgentMode, reason: str, *, flatten: bool = False) -> int:
    container = Container.build(settings)
    if (flatten or mode is AgentMode.KILLED) and container.broker is None:
        raise RuntimeError("flattening controls require Alpaca credentials")
    if mode is AgentMode.RUNNING:
        if container.broker is None:
            raise RuntimeError("resume requires Alpaca credentials")
        snapshot = container.broker.reconciliation_snapshot()
        ReconciliationService.validate_snapshot(snapshot)
        if snapshot.positions or snapshot.open_orders:
            raise RuntimeError("first-slice resume requires no positions or open orders")
        state = container.store.get_agent_state()
        if state.active_order_id is not None:
            execution = container.store.get_order(state.active_order_id)
            if execution is None:
                raise RuntimeError("active order has no durable execution record")
            broker_order = container.broker.get_order_by_client_id(state.active_order_id)
            status = (
                broker_order.status.rsplit(".", 1)[-1].lower()
                if broker_order is not None
                else "missing"
            )
            terminal = status in {
                "canceled",
                "expired",
                "filled",
                "rejected",
                "replaced",
            }
            expired_and_missing = (
                status == "missing" and snapshot.clock.timestamp >= execution.plan.expires_at
            )
            if not terminal and not expired_and_missing:
                raise RuntimeError("active order is not terminal; refusing resume")
            container.store.clear_active_order(state.active_order_id)
        if not container.store.get_agent_state().is_reconciled:
            container.reconciliation_service().reconcile()
    record = DecisionRecord.create(
        decision_type="OPERATOR_ACTION",
        summary=f"operator changed mode to {mode}: {reason}",
        payload={"mode": mode, "reason": reason},
    )
    state = container.store.transition_agent_mode(mode, reason=reason, record=record)
    if flatten or mode is AgentMode.KILLED:
        assert container.broker is not None
        container.broker.flatten()
    print(
        json.dumps(
            {
                "paper": True,
                "mode": state.mode,
                "reconciled": state.is_reconciled,
                "reason": state.reason,
            },
            indent=2,
        )
    )
    return 0


def main() -> int:
    load_dotenv()
    logging.basicConfig(level=logging.INFO)
    parser = argparse.ArgumentParser(prog="catalyst-router")
    subparsers = parser.add_subparsers(dest="command", required=True)
    subparsers.add_parser("check-alpaca", help="read and sanitize Alpaca paper account state")
    subparsers.add_parser("reconcile", help="persist a fenced paper-account reconciliation")
    subparsers.add_parser("worker", help="run the always-on shadow inference worker")
    for command in ("resume", "pause", "flatten", "kill"):
        control = subparsers.add_parser(command, help=f"{command} paper execution")
        control.add_argument("--reason", required=True)
    serve = subparsers.add_parser("serve", help="run the local API")
    serve.add_argument("--host", default="127.0.0.1")
    serve.add_argument("--port", type=int, default=8000)
    args = parser.parse_args()

    if args.command == "check-alpaca":
        return _check_alpaca(Settings.from_env())
    if args.command == "reconcile":
        return _reconcile(Settings.from_env())
    if args.command == "worker":
        return _worker(Settings.from_env())
    if args.command == "resume":
        return _set_mode(Settings.from_env(), AgentMode.RUNNING, args.reason)
    if args.command == "pause":
        return _set_mode(Settings.from_env(), AgentMode.PAUSED, args.reason)
    if args.command == "flatten":
        return _set_mode(Settings.from_env(), AgentMode.PAUSED, args.reason, flatten=True)
    if args.command == "kill":
        return _set_mode(Settings.from_env(), AgentMode.KILLED, args.reason)
    if args.command == "serve":
        uvicorn.run("catalyst_router.api:app", host=args.host, port=args.port, reload=False)
        return 0
    parser.error(f"unknown command: {args.command}")
    return 2


if __name__ == "__main__":
    raise SystemExit(main())

